// Keep the native test files as the single source for the example's fixtures.
const fs = require('node:fs');
const path = require('node:path');
const directory = path.resolve(__dirname, '../../tests/audio');
const fixtures = JSON.parse(fs.readFileSync(path.join(directory, 'fixtures.json'), 'utf8'));
const data = fixtures.map(({ appleSupported, ...fixture }) => ({
  ...fixture,
  base64: fs.readFileSync(path.join(directory, 'fixtures', fixture.filename)).toString('base64'),
}));
fs.writeFileSync(path.resolve(__dirname, '../audioFixtures.ts'),
  '// Generated by scripts/audio-fixtures.cjs. Do not edit.\nexport const audioFixtures = ' + JSON.stringify(data, null, 2) + ' as const;\n');
